dir:






























































&DefaultButton;




function dir$syscodechange(p){
  this.constructor(p);
}
dir$syscodechange.prototype = new DirEvent();
dir$syscodechange.prototype.beforeInit = function(){
  var p = this._dir, g = p.options.parent;
  p.field('code_type').valueDefault = g.options._code_type;
}
dir$syscodechange.prototype.afterInit = function(){
  var p = this._dir, g = p.options.parent;

}
dir$syscodechange.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
    case 'old_value':
      if (v != "") {
        p.request('checkOldCode', '', ['code_type', 'old_value'], function(pp, d){
          d = new DataRow(d);
          p.valForm('old_label', p.msg(d.val('old_label')));
        })
      }else {
        p.valForm('old_label', '');
      }
      break;
    case 'new_value':
      if (v != "") {
        p.request('checkNewCode', '', ['code_type', 'new_value'], function(pp, d){
          d = new DataRow(d);
          p.valForm('new_label', p.msg(d.val('new_label')));
        })
      }else {
        p.valForm('new_label', '');
      }
      break;
    default:
      break;
  }
}
dir$syscodechange.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir;
  switch (id){
    case 'ok':
      if (p.valForm('old_label') != '') {p.jObject('old_value').focus(); return false;}
      if (p.valForm('old_value').trim() == p.valForm('new_value').trim()) {p.jObject('new_value').focus(); return false;}
      break;
    default:
      break;
  }
  return true;
}








declare @q nvarchar(3000)
select @q = 'if not exists(select 1 from ' + ctable + ' where ' + cfield + ' = ''' + dbo.ISWIFTFunctionReplaceSQLValue(@old_value) + ''') 
  select ''notExistsOldCode'' as [old_label]
  else select '''' as [#old_label]
' from syslistchangecode where code = @code_type
exec (@q)







declare @q nvarchar(3000)
select @q = 'if exists(select 1 from ' + ctable + ' where ' + cfield + ' = ''' + dbo.ISWIFTFunctionReplaceSQLValue(@new_value) + ''') 
  select 1 as [!xtype], ''existsNewCode'' as new_label
  else select 0 as [!xtype], '''' as [#new_label]
' from syslistchangecode where code = @code_type
exec (@q)







